import{_ as r,o,c as s,a5 as n}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"1","description":"在 JavaScript/TypeScript 中，\\\\ \\\\ 1 是一个​ ​ 右移运算符 ​ ​，它的作用是将数字的二进制表示​ ​ 向右移动 1 位 ​ ​，相当于​ ​ 整数除以 2 并向下取整 ​ ​。 ​​ 具体解释 ​​ 在你的 binarySearch 函数中： co。","frontmatter":{"title":"1","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","语法、变量与数据"],"description":"在 JavaScript/TypeScript 中，\\\\ \\\\ 1 是一个​ ​ 右移运算符 ​ ​，它的作用是将数字的二进制表示​ ​ 向右移动 1 位 ​ ​，相当于​ ​ 整数除以 2 并向下取整 ​ ​。 ​​ 具体解释 ​​ 在你的 binarySearch 函数中： co。","sidebarWeight":89,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/运算符/ 1/1.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/02-语法、变量与数据/1/1.md","filePath":"posts/JavaScript系统教程/02-语法、变量与数据/1/1.md"}'),g={name:"posts/JavaScript系统教程/02-语法、变量与数据/1/1.md"};function l(a,t,i,e,c,p){return o(),s("div",null,[...t[0]||(t[0]=[n('<div><h1 id="_1" tabindex="-1">1 <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1&quot;">​</a></h1><blockquote><p>本节目标：理解“1”的核心思路，并能把它用于实际开发或面试表达。 在 JavaScript/TypeScript 中，&gt;&gt; 1 是一个​<strong>​<strong><strong>右移运算符</strong></strong>​</strong>​，它的作用是将数字的二进制表示​<strong>​<strong><strong>向右移动 1 位</strong></strong>​</strong>​，相当于​<strong>​<strong><strong>整数除以 2 并向下取整</strong></strong>​</strong>​。</p></blockquote><p><strong>​​<strong><strong>具体解释</strong></strong>​​</strong> 在你的 binarySearch 函数中： const m = (l + r) &gt;&gt; 1; 等价于： const m = Math.floor((l + r) / 2); 即计算 l 和 r 的中间索引 m，用于二分查找。</p><p>**​​****为什么用 &gt;&gt; 1 而不是 / 2？**<strong>​​</strong></p><ol><li>​<strong>​<strong><strong>性能优化</strong></strong>​</strong>​（微优化） <ul><li>位运算 (&gt;&gt; 1) 通常比除法 (/ 2) 和 Math.floor() 更快，因为 CPU 可以直接处理二进制移位。</li><li>在早期的 JavaScript 引擎中，这种优化比较明显，但现代引擎（如 V8）已经能自动优化 / 2，所以性能差距很小。</li></ul></li><li>​<strong>​<strong><strong>代码风格</strong></strong>​</strong>​ <ul><li>某些开发者喜欢用 &gt;&gt; 1 来表示“取中间值”，尤其是在算法或底层代码中，因为它更简洁。</li><li>但可读性较差，新手可能不理解它的含义。</li></ul></li></ol><p><strong>​​</strong><strong>注意事项****​​</strong></p><ol><li>​<strong>​<strong><strong>仅适用于整数</strong></strong>​</strong>​&gt;&gt; 是​<strong>​<strong><strong>有符号右移</strong></strong>​</strong>​，会丢弃小数部分，所以 5 &gt;&gt; 1 === 2（相当于 Math.floor(5 / 2)）。如果 (l + r) 是奇数（如 7），7 &gt;&gt; 1 === 3（正确结果）。</li><li>​<strong>​<strong><strong>边界情况</strong></strong>​</strong>​ <ul><li>如果 (l + r) 非常大（接近 Number.MAX_SAFE_INTEGER），(l + r) &gt;&gt; 1 可能溢出，但 (l + r) / 2 不会。</li><li>更安全的写法是： const m = l + ((r - l) &gt;&gt; 1); // 避免溢出</li></ul></li></ol><p><strong>​​<strong><strong>总结</strong></strong>​​</strong></p><ul><li>&gt;&gt; 1 是​<strong>​<strong><strong>右移 1 位</strong></strong>​</strong>​，相当于 Math.floor(x / 2)，用于快速计算中间索引。</li><li>在二分查找中常见，但现代 JS 引擎优化后，直接写 / 2 或 Math.floor() 也是可以的。</li><li>如果追求极致性能或写底层代码，可以用 &gt;&gt; 1；否则建议用更易读的写法。</li></ul></div>',1)])])}const S=r(g,[["render",l]]);export{d as __pageData,S as default};
